# READ-ONLY — this cell does not modify anything.
# VARIANT bounded_dbu: reproduces the DBU figure cited above against system.billing.usage.
# (perf_metric / pilot / none items: delete this cell and keep the next one.)
# Run this first to confirm the number before acting on anything.

workspace_id = "{{WORKSPACE_ID}}"  # scope: this notebook covers exactly this workspace

result = spark.sql(f"""
    SELECT
        workspace_id,
        {{GROUPING_DIMENSIONS}},                 -- e.g. sku_name, endpoint_name, job_id
        ROUND(SUM(usage_quantity), 2)  AS total_dbus   -- DBU via usage_quantity (the real column)
    FROM system.billing.usage
    WHERE workspace_id    = '{workspace_id}'
      AND {{PRODUCT_FILTER}}                      -- e.g. billing_origin_product = 'VECTOR_SEARCH'
      AND {{DATE_RANGE_FILTER}}                   -- e.g. usage_date >= date_sub(current_date(), 30)
    GROUP BY workspace_id, {{GROUPING_DIMENSIONS}}
    ORDER BY total_dbus DESC
""")

result.display()

# Expected: total_dbus in the result should match {{RECOVERABLE_DBU}} within rounding.
# If it differs materially, stop — do not proceed to the remediation cell — and re-verify the finding.

