# READ-ONLY — this cell does not modify anything.
# VARIANT perf_metric / pilot / none: reproduces the cited metric by day (the baseline).
# No DBU figure is assumed. (bounded_dbu items: delete this cell and keep the one above.)
# Replace the example query with the catalog entry's verify query in public system.* names,
# e.g. daily queueing on one SQL warehouse:

workspace_id = "{{WORKSPACE_ID}}"
metric_target_id = "{{TARGET_ID}}"  # the warehouse or job id named in the finding

metric = spark.sql(f"""
    SELECT
        DATE(start_time)                                                  AS day,
        COUNT(*)                                                          AS queries,
        ROUND(100 * AVG(CASE WHEN waiting_at_capacity_duration_ms > 0 THEN 1 ELSE 0 END), 1)
                                                                          AS queued_pct,
        ROUND(PERCENTILE(waiting_at_capacity_duration_ms, 0.95) / 1000, 1) AS p95_capacity_wait_s
    FROM system.query.history
    WHERE workspace_id = '{workspace_id}'
      AND compute.warehouse_id = '{metric_target_id}'
      AND start_time >= date_sub(current_date(), 7)
      AND start_time <  current_date()                                     -- full days only
    GROUP BY DATE(start_time)
    ORDER BY day
""")

metric.display()

# Expected: the metric matches {{SIZING_VALUE}} {{SIZING_UNIT}} from the evidence pack within rounding.
# If it differs materially, stop and re-verify the finding before acting.

