# COMMAND ----------

# READ-ONLY — post-change measurement: a baseline window and an after window, run separately.
# Each window is its own query, so per-day / per-run figures use that window's own denominators.
# Every window has an explicit start AND end (start + 7 full days) — never an open-ended
# `< current_date()`, which silently grows the after window when the notebook is run later.
# Scope it to the exact cited population: the cited source_type / source_id / client_application
# for OPP-WH-SCAN (not a warehouse-wide average); successful CRON parent runs and the wait task's
# successful, non-zero-duration attempts for OPP-JOB-WAIT-TASK.
# Measure the catalog's canonical metric (sizing.metric) on the target, e.g. for
# OPP-SERVERLESS-STANDARD-MODE: CRON DBU per run and wall-clock per run of the target job
# (vt-job-runs), not the workspace performance-mode mix. Example: daily queueing on one warehouse.
import datetime as _dt  # noqa: E402

change_date = ""  # YYYY-MM-DD the operator applied the change — enter it; never pre-fill a historical timestamp
if not change_date:
    raise ValueError("Set change_date (YYYY-MM-DD) before running the post-change measurement.")
_c = _dt.date.fromisoformat(change_date)
_day = lambda n: str(_c + _dt.timedelta(days=n))  # noqa: E731
windows = {
    "baseline": (_day(-7), _day(-1)),  # the 7 full days before the change
    "after": (_day(1), _day(7)),       # the first full day after the change, for 7 days
}

for name, (start, end) in windows.items():
    spark.sql(f"""
        SELECT
            '{name}'                                                                       AS comparison_window,
            COUNT(*)                                                                         AS queries,
            ROUND(100 * AVG(CASE WHEN waiting_at_capacity_duration_ms > 0 THEN 1 ELSE 0 END), 1) AS queued_pct,
            ROUND(PERCENTILE(waiting_at_capacity_duration_ms, 0.95) / 1000, 1)               AS p95_capacity_wait_s
        FROM system.query.history
        WHERE workspace_id = '{workspace_id}'
          AND compute.warehouse_id = '{metric_target_id}'
          AND start_time >= DATE'{start}'
          AND start_time <  DATE_ADD(DATE'{end}', 1)
    """).display()

